class Solution {
public:
    vector<int> deckRevealedIncreasing(vector<int>& deck) {
        int n = deck.size();
        sort(deck.begin(), deck.end());
        vector<int> result(n);
        deque<int> indices;
        for (int i = 0; i < n; i++) {
            indices.push_back(i);
        }
        for (int i = 0; i < n; i++) {
            int idx = indices.front();
            indices.pop_front();
            result[idx] = deck[i];
            if (!indices.empty()) {
                indices.push_back(indices.front());
                indices.pop_front();
            }
        }
        return result;
    }
};
